# Queue handler 0; each handler owns an independent queue.
class Handler0:
    def __init__(self, queue, client, retries=2):
        self.queue = queue
        self.client = client
        self.retries = retries
        self.finished = {}

    def process(self, job):
        if job['id'] in self.finished:
            return self.finished[job['id']]
        for attempt in range(self.retries):
            try:
                result = self.client.send(job['payload'])
                self.finished[job['id']] = result
                return result
            except Exception:
                continue
        self.queue.ack(job['id'])
        return None

